def replace_words_with_roots(roots, sentence):
    trie = {}
    END = "$end"
    for root in roots:
        node = trie
        for ch in root:
            node = node.setdefault(ch, {})
        node[END] = True

    def shortest_root(word):
        node = trie
        for i, ch in enumerate(word):
            if ch not in node:
                return word
            node = node[ch]
            if node.get(END):
                return word[: i + 1]
        return word

    return " ".join(shortest_root(w) for w in sentence.split(" "))
